private formatValidationErrors(toolName: string, errors?: readonly unknown[] | null): string {
  if (!errors || errors.length === 0) {
    return `Invalid input for tool "${toolName}"`;
  }
  const descriptions: string[] = [];
  for (const err of errors) {
    if (!isRecord(err)) {
      continue;
    }
    const rawPath =
      typeof err.instancePath === 'string' ? err.instancePath : typeof err.dataPath === 'string' ? err.dataPath : '';
    const params = isRecord(err.params) ? err.params : undefined;
    const missingProp = typeof params?.missingProperty === 'string' ? params.missingProperty : '';
    const fieldPath = rawPath ? cleanInstancePath(rawPath) : missingProp;

    if (err.keyword === 'required' && missingProp) {
      descriptions.push(`missing required property "${missingProp}"`);
    } else if (err.keyword === 'type' && typeof params?.type === 'string') {
      const expectedType: string = params.type;
      descriptions.push(`property "${fieldPath}" must be of type ${expectedType}`);
    } else if (err.keyword === 'enum' && Array.isArray(params?.allowedValues)) {
      descriptions.push(`property "${fieldPath}" must be one of allowed values`);
    } else {
      const msg = typeof err.message === 'string' ? err.message : 'is invalid';
      descriptions.push(fieldPath ? `property "${fieldPath}" ${msg}` : msg);
    }
  }
  if (descriptions.length === 0) {
    return `Invalid input for tool "${toolName}"`;
  }
  return `Invalid input for tool "${toolName}": ${descriptions.join('; ')}`;
}

