private formatSingleValidationError(err: Record<string, unknown>): string {
  const rawPath =
    typeof err.instancePath === 'string' ? err.instancePath : typeof err.dataPath === 'string' ? err.dataPath : '';
  const params = isRecord(err.params) ? err.params : undefined;
  const missingProp = typeof params?.missingProperty === 'string' ? params.missingProperty : '';
  const fieldPath = rawPath ? cleanInstancePath(rawPath) : missingProp;

  if (err.keyword === 'required' && missingProp) {
    return `missing required property "${missingProp}"`;
  }
  if (err.keyword === 'type' && typeof params?.type === 'string') {
    const expectedType: string = params.type;
    return `property "${fieldPath}" must be of type ${expectedType}`;
  }
  if (err.keyword === 'enum' && Array.isArray(params?.allowedValues)) {
    return `property "${fieldPath}" must be one of allowed values`;
  }
  const fallbackMessage = typeof err.message === 'string' ? err.message : 'is invalid';
  return fieldPath ? `property "${fieldPath}" ${fallbackMessage}` : fallbackMessage;
}

